css:
[data-bz-node="integ"] { background: var(--card); border-block: 1px solid var(--line-soft); }
[data-bz-node="integ"] .bz-eyebrow { color: var(--muted); font: 600 13.5px/1.4 var(--font-body); letter-spacing: .06em; margin-bottom: var(--space-5); }
[data-bz-node="integ"] .bz-logos { border: 0; padding: 0; justify-content: center; gap: 28px 56px; }
[data-bz-node="integ"] .bz-logo img { height: 34px; width: auto; max-width: 150px; object-fit: contain; filter: grayscale(1); opacity: .62; transition: filter .2s ease, opacity .2s ease; }
[data-bz-node="integ"] .bz-logo img:hover { filter: none; opacity: 1; }
/* Marquee state, switched on by the component script. Without it — in the
   editor and with JS off — the logos are a centred, wrapping row. */
[data-bz-node="integ"] .is-marquee-host { overflow: hidden; -webkit-mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent); mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent); }
[data-bz-node="integ"] .bz-logos.is-marquee { flex-wrap: nowrap; justify-content: flex-start; width: max-content; animation: bz-marquee 42s linear infinite; }
[data-bz-node="integ"] .is-marquee-host:hover .bz-logos.is-marquee { animation-play-state: paused; }
@keyframes bz-marquee { from { transform: translateX(0) } to { transform: translateX(-50%) } }
@media (prefers-reduced-motion: reduce) { [data-bz-node="integ"] .bz-logos.is-marquee { animation: none; } }

js:
/* Integrations strip: turn the wrapping logo row into a continuous marquee.
   The un-enhanced row is the editor's and the no-JS layout; this only adds the
   motion, and not at all when the visitor prefers reduced motion. */
(function () {
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  document.querySelectorAll('[data-bz-section="integrations-strip"] .bz-logos').forEach(function (row) {
    if (row.classList.contains('is-marquee')) return;
    Array.prototype.slice.call(row.children).forEach(function (logo) {
      var copy = logo.cloneNode(true);
      copy.setAttribute('aria-hidden', 'true');
      copy.querySelectorAll('img').forEach(function (img) { img.alt = ''; });
      row.appendChild(copy);
    });
    row.parentNode.classList.add('is-marquee-host');
    row.classList.add('is-marquee');
  });
})();
